
#!/usr/bin/env bash
set -Eeuo pipefail

AWS_REGION="us-east-2"
AWS_ACCOUNT_ID="242627333067"

ECR_REGISTRY="${AWS_ACCOUNT_ID}.dkr.ecr.${AWS_REGION}.amazonaws.com"

DEPLOY_DIR="/opt/aws-pratice"
COMPOSE_FILE="${DEPLOY_DIR}/compose.prod.yml"

echo "Starting deployment..."

# Wait for EC2 initialization to finish.
timeout 900 cloud-init status --wait

# Ensure Datadog initialization completed successfully.
test -f /var/lib/aws-pratice/observability-ready

# Verify that the Datadog Agent is healthy.
docker exec dd-agent agent health >/dev/null

# Load database configuration generated by Terraform.
source /etc/aws-pratice-deploy.env

# Validate required database settings.
: "${SECRET_ARN:?Missing database secret ARN}"
: "${DB_HOST:?Missing database host}"
: "${DB_NAME:?Missing database name}"

cd "$DEPLOY_DIR"

# Check required tools.
command -v aws >/dev/null
command -v docker >/dev/null
command -v python3 >/dev/null
docker compose version >/dev/null

# Retrieve database credentials from Secrets Manager.
echo "Retrieving database credentials..."

SECRET_JSON="$(aws secretsmanager get-secret-value \
  --secret-id "$SECRET_ARN" \
  --region "$AWS_REGION" \
  --query SecretString \
  --output text)"

# Build the database URL without writing credentials to disk.
export SECRET_JSON DB_HOST DB_NAME

DATABASE_URL="$(python3 - <<'PY'
import json
import os
from urllib.parse import quote

secret = json.loads(os.environ["SECRET_JSON"])

username = quote(secret["username"], safe="")
password = quote(secret["password"], safe="")
host = os.environ["DB_HOST"]
database = os.environ["DB_NAME"]

print(
    f"postgresql+psycopg://{username}:{password}"
    f"@{host}:5432/{database}"
)
PY
)"

unset SECRET_JSON
export DATABASE_URL

# Remove the database URL when the script exits.
trap 'unset DATABASE_URL' EXIT

# Authenticate Docker with Amazon ECR.
echo "Authenticating with Amazon ECR..."

aws ecr get-login-password --region "$AWS_REGION" |
  docker login \
    --username AWS \
    --password-stdin "$ECR_REGISTRY"

# Download application images.
echo "Pulling Docker images..."

docker compose \
  -f "$COMPOSE_FILE" \
  pull

# Start or update the application.
echo "Starting containers..."

docker compose \
  -f "$COMPOSE_FILE" \
  up -d \
  --remove-orphans \
  --force-recreate

# Remove unused Docker images.
echo "Cleaning up unused images..."

docker image prune -f

# Show running containers.
echo "Checking containers..."

docker compose \
  -f "$COMPOSE_FILE" \
  ps

echo "Deployment completed successfully."
